import json
import os
from typing import Any

import jax
import jax.numpy as jnp
import numpy as np

BASE_DIR = os.path.dirname(os.path.abspath(__file__))


def _load(path: str) -> Any:
    full_path = os.path.join(BASE_DIR, path)
    if path.endswith('.npy'):
        return np.load(full_path)
    if path.endswith('.npz'):
        return np.load(full_path)
    raise ValueError(f"Unsupported input format: {path}")


def _save(path: str, arr: Any) -> None:
    full_path = os.path.join(BASE_DIR, path)
    np.save(full_path, np.array(arr))


def task_basic_reduce(input_path: str) -> np.ndarray:
    x = jnp.array(_load(input_path))
    return jnp.mean(x, axis=1)


def task_map_square(input_path: str) -> np.ndarray:
    x = jnp.array(_load(input_path))
    return jnp.square(x)


def task_grad_logistic(input_path: str) -> np.ndarray:
    data = _load(input_path)
    x = jnp.array(data["x"])
    y = jnp.array(data["y"])
    w = jnp.array(data["w"])

    def loss_fn(w_vec: jnp.ndarray, x_mat: jnp.ndarray, y_vec: jnp.ndarray) -> jnp.ndarray:
        logits = y_vec * (x_mat @ w_vec)
        return jnp.mean(jnp.logaddexp(0.0, -logits))

    grad_w = jax.grad(loss_fn)(w, x, y)
    return grad_w


def task_scan_rnn(input_path: str) -> np.ndarray:
    data = _load(input_path)
    seq = jnp.array(data["seq"])
    init = jnp.array(data["init"])
    Wx = jnp.array(data["Wx"])
    Wh = jnp.array(data["Wh"])
    b = jnp.array(data["b"])

    def step(h_prev: jnp.ndarray, x_t: jnp.ndarray):
        h_t = jnp.tanh(Wx @ x_t + Wh @ h_prev + b)
        return h_t, h_t

    _, hs = jax.lax.scan(step, init, seq)
    return hs


def task_jit_mlp(input_path: str) -> np.ndarray:
    data = _load(input_path)
    X = jnp.array(data["X"])
    W1 = jnp.array(data["W1"])
    b1 = jnp.array(data["b1"])
    W2 = jnp.array(data["W2"])
    b2 = jnp.array(data["b2"])

    @jax.jit
    def mlp(x_batch: jnp.ndarray) -> jnp.ndarray:
        h = jax.nn.relu(x_batch @ W1 + b1)
        return h @ W2 + b2

    return mlp(X)


def main() -> None:
    problem_path = os.path.join(BASE_DIR, "problem.json")
    with open(problem_path, "r", encoding="utf-8") as f:
        tasks = json.load(f)

    for task in tasks:
        task_id = task["id"]
        input_path = task["input"]
        output_path = task["output"]

        if task_id == "basic_reduce":
            result = task_basic_reduce(input_path)
        elif task_id == "map_square":
            result = task_map_square(input_path)
        elif task_id == "grad_logistic":
            result = task_grad_logistic(input_path)
        elif task_id == "scan_rnn":
            result = task_scan_rnn(input_path)
        elif task_id == "jit_mlp":
            result = task_jit_mlp(input_path)
        else:
            raise ValueError(f"Unknown task id: {task_id}")

        _save(output_path, result)


if __name__ == "__main__":
    main()
PY"}
